const req = $node['Webhook Intake'].json || {};
const q = req.query || {};
const cfg = $node['Config'].json || {};
const timezone = String(cfg.timezone || 'America/Los_Angeles');
const view = String(q.view || 'overview');
const range = String(q.range || '30d');
const from = q.from ? String(q.from) : '';
const to = q.to ? String(q.to) : '';

function isoDate(date) {
  return date.toISOString().slice(0, 10);
}

function subtractDays(date, days) {
  const d = new Date(date.getTime());
  d.setUTCDate(d.getUTCDate() - days);
  return d;
}

const map = { '7d': 7, '30d': 30, '90d': 90 };
let endDate = to || isoDate(new Date());
let startDate = from;
if (!startDate) {
  const days = map[range] || 30;
  startDate = isoDate(subtractDays(new Date(`${endDate}T00:00:00Z`), days - 1));
}

return [{
  json: {
    workflowName: String(cfg.workflowName || 'LT - Report Executive Summary API'),
    timezone,
    view,
    range,
    from,
    to,
    startDate,
    endDate,
  },
}];

const row = $input.first()?.json || {};
const payload = row.payload || row;
const summary = payload.summary || {};
const channels = Array.isArray(payload.channelBreakdown) ? payload.channelBreakdown : [];
const pipelines = Array.isArray(payload.pipelineDropoff) ? payload.pipelineDropoff : [];
const stages = Array.isArray(payload.stageDropoff) ? payload.stageDropoff : [];
const health = Array.isArray(payload.health) ? payload.health : [];

const traffic = Number(summary.trafficNumeric ?? summary.sessions ?? 0);
const leads = Number(summary.leadsNumeric ?? summary.contactsCreated ?? 0);
const sales = Number(summary.salesNumeric ?? summary.closedWonCount ?? 0);
const revenue = Number(summary.closedWonRevenue ?? 0);

const coreQuestions = {
  attractingTraffic: traffic > 0 ? 'Yes' : 'GA4 pending',
  trafficToLeads: traffic > 0 && leads > 0 ? 'Partial' : 'Pending',
  leadsToSales: leads > 0 && sales > 0 ? 'Yes' : 'Partial',
};

const channelBreakdown = channels.map((item) => ({
  label: String(item.channel || item.traffic_source || 'Other'),
  value: Number(item.sessions || 0),
  sessions: Number(item.sessions || 0),
  leads: Number(item.leads || 0),
  opportunities: Number(item.opportunities || 0),
  closedWonRevenue: Number(item.closed_won_revenue || 0),
}));
const maxChannel = Math.max(1, ...channelBreakdown.map((item) => item.value || 0));
for (const item of channelBreakdown) item.percent = Math.max(3, Math.round((item.value / maxChannel) * 100));

const pipelineDropoff = pipelines.map((item) => ({
  label: String(item.pipeline || 'Pipeline'),
  value: Number(item.moved_out_count || item.moved_in_count || item.stage_count || 0),
  stageCount: Number(item.stage_count || 0),
  movedIn: Number(item.moved_in_count || 0),
  movedOut: Number(item.moved_out_count || 0),
  wonCount: Number(item.won_count || 0),
  lostCount: Number(item.lost_count || 0),
}));
const maxPipeline = Math.max(1, ...pipelineDropoff.map((item) => item.value || 0));
for (const item of pipelineDropoff) item.percent = Math.max(3, Math.round((item.value / maxPipeline) * 100));

const topStage = stages.reduce((best, current) => {
  if (!best) return current;
  return (Number(current.lost_count || 0) > Number(best.lost_count || 0)) ? current : best;
}, null);

const trafficGaps = {
  sessions: traffic,
  landingPages: Number(summary.trafficGapLandingPages || 0),
  searchClicks: Number(summary.gscClicks || 0),
  formSubmissions: Number(summary.formSubmissions || 0),
};

const salesQuality = {
  avgCycleLengthDays: null,
  bestChannel: channelBreakdown[0]?.label || 'GHL ready',
  topLossReason: topStage ? String(topStage.stage || topStage.pipeline || 'No response') : 'No response',
  closedWonRevenue: revenue,
};

return [{
  json: {
    window: payload.window || {},
    summary,
    traffic: traffic > 0 ? String(traffic) : 'GA4 pending',
    leads: String(leads),
    sales: String(sales),
    coreQuestions,
    channelBreakdown,
    pipelineDropoff,
    stageDropoff: stages,
    trafficGaps,
    salesQuality,
    health,
  },
}];

